// EcoShield core logic. ONE source of truth: tests run this file in Node, and the n8n generator pastes the same text into Code nodes.
// Everything here is plain code. No LLM, no network. SYNTHETIC DATA, ASSUMED TARIFF (unverified, see TARIFF).

const LIMITS = { OCCUPIED_MAX_C: 24, UNOCCUPIED_PRECOOL_MAX_C: 27, HEAT_OUTDOOR_C: 38, LEAK_MIN_LPH: 10, WATCH_MIN_LPH: 3, LEAK_NIGHTS: 2, LEAK_RUN_HOURS: 24, NIGHT_FIRST: 1, NIGHT_LAST: 5, GAP_LIMIT: 0.2, MIN_NAME_LEN: 2 };
const MONTH_DAYS = 30, TODAY = 22;          // day 1 is a Monday; days 6,7,13,14,20,21,27,28 are weekends; day 22 is a Monday
const L_PER_IG = 4.54609;
// ASSUMED tariff from secondary web guides, NOT checked against DEWA. Water tiers conflict between sources. A school may pay a commercial rate.
const TARIFF = {
  verified: false, source: 'secondary web guides, 2026-11-19; unverified',
  electricity: { unit: 'kWh', slabs: [{ upto: 2000, rate: 0.23 }, { upto: 4000, rate: 0.28 }, { upto: 6000, rate: 0.32 }, { upto: Infinity, rate: 0.38 }], fuel_surcharge_per_kwh: 0.065 },
  water: { unit: 'imperial gallon', slabs: [{ upto: 6000, rate: 0.03 }, { upto: 12000, rate: 0.035 }, { upto: Infinity, rate: 0.04 }] }
};

// ---------- scenarios (the 10 demo cases) ----------
// now: {day, hour, occupied, outdoor_c}. request: what someone or some automation asks the system to do.
const SCENARIOS = [
  { id: 1, name: 'Overnight hidden pipe leak', desc: 'Steady 45 L/h at 2 AM while the block is empty, since day 17.', leak: { startDay: 17, lph: 45 }, now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'MAIN_WATER_SHUTOFF' }, expect: { leak: 'LEAK', rule: 'needs_approval' } },
  { id: 2, name: 'Normal month', desc: 'Nothing wrong. A routine setpoint change inside the limits.', now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'SETPOINT', setpoint_c: 23 }, expect: { leak: 'NO_LEAK', rule: 'needs_approval' } },
  { id: 3, name: 'Weekend-long leak', desc: 'Leak started Saturday morning (day 20) and ran all weekend.', leak: { startDay: 20, lph: 38 }, now: { hour: 9, occupied: 1, outdoor_c: 38 }, request: { type: 'MAIN_WATER_SHUTOFF' }, expect: { leak: 'LEAK', rule: 'needs_approval' } },
  { id: 4, name: 'Small drip below the threshold', desc: 'About 6 L/h all day since day 10. Under the 10 L/h rule, so only a watch.', drip: { startDay: 10, lph: 6 }, now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'SETPOINT', setpoint_c: 24 }, expect: { leak: 'WATCH', rule: 'needs_approval' } },
  { id: 5, name: 'Night cleaning crew (not a leak)', desc: 'Water used 2 to 4 AM, but the occupancy flag says people are there.', cleaning: { lph: 60 }, now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'SETPOINT', setpoint_c: 24 }, expect: { leak: 'NO_LEAK', rule: 'needs_approval' } },
  { id: 6, name: '46 C afternoon, AC shutoff request', desc: 'Exam hours, 46 C outside. An energy-saving automation asks to switch cooling off.', now: { hour: 14, occupied: 1, outdoor_c: 46 }, peakOut: 46, request: { type: 'COOLING_OFF' }, expect: { leak: 'NO_LEAK', rule: 'cooling_off_in_heat', status: 'BLOCKED' } },
  { id: 7, name: 'Pre-cooling request above the ceiling', desc: 'Empty building at 5 AM. Automation asks for a 30 C pre-cooling setpoint.', now: { hour: 5, occupied: 0, outdoor_c: 33 }, request: { type: 'SETPOINT', setpoint_c: 30 }, expect: { leak: 'NO_LEAK', rule: 'unoccupied_over_precool_ceiling', status: 'BLOCKED' } },
  { id: 8, name: 'High month crosses a slab', desc: 'A larger cooling load pushes the month into the second electricity slab.', elecScale: 2.1, now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'SETPOINT', setpoint_c: 24 }, expect: { leak: 'NO_LEAK', rule: 'needs_approval', slabCrossed: true } },
  { id: 9, name: 'Missing meter hours', desc: 'The meter dropped out for many night hours.', gap: true, now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'SETPOINT', setpoint_c: 24 }, expect: { leak: 'INSUFFICIENT_DATA', rule: 'needs_approval' } },
  { id: 10, name: 'Attempt to send the occupancy schedule out', desc: 'A request asks to send room-by-room occupancy to a cloud AI.', now: { hour: 14, occupied: 1, outdoor_c: 41 }, request: { type: 'EXPORT_OCCUPANCY' }, expect: { leak: 'NO_LEAK', rule: 'privacy_export_blocked', status: 'BLOCKED' } }
];

// ---------- synthetic dataset (deterministic) ----------
function rng(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const isWeekend = (d) => ((d - 1) % 7) >= 5;
function genScenario(def) {
  const rnd = rng(1000 + def.id * 17), rows = [];
  const peak = def.peakOut || 41, low = peak - 12, scale = def.elecScale || 1, nowH = def.now.hour;
  for (let d = 1; d <= TODAY; d++) for (let h = 0; h < 24; h++) {
    if (d === TODAY && h >= nowH) break;
    const wk = isWeekend(d), school = !wk && h >= 7 && h <= 15;
    let occupied = school ? 1 : 0;
    const dayPeak = (d === TODAY && def.peakOut) ? def.peakOut : peak - 1.5 + rnd() * 3;
    const out = Math.round((dayPeak - 12 + 12 * (0.5 + 0.5 * Math.sin(2 * Math.PI * (h - 9) / 24))) * 10) / 10;
    let water = school ? 120 + rnd() * 80 : (rnd() * 1.4);
    if (def.cleaning && !wk && h >= 2 && h <= 4) { water = def.cleaning.lph + rnd() * 6; occupied = 1; }
    if (def.leak && d >= def.leak.startDay) water += def.leak.lph + (rnd() - 0.5) * 2;
    if (def.drip && d >= def.drip.startDay) water += def.drip.lph + (rnd() - 0.5);
    let kwh = (school ? 3.0 + 0.25 * Math.max(0, out - 24) : 0.8 + (wk ? 0.1 : 0.2)) * scale * (0.95 + rnd() * 0.1);
    if (def.gap && h >= 0 && h <= 5 && d >= 15 && d <= 21 && rnd() < 0.5) { water = null; kwh = null; }
    rows.push({ day: d, hour: h, dow: (d - 1) % 7, water_lph: water === null ? null : Math.round(water * 10) / 10, kwh: kwh === null ? null : Math.round(kwh * 100) / 100, occupied, outdoor_c: out, setpoint_c: occupied ? 24 : 27 });
  }
  return rows;
}

// ---------- tool 1: local meter + occupancy (full record, stays on the device) ----------
function get_local_meter_and_occupancy(id) {
  const def = SCENARIOS.find(s => s.id === +id); if (!def) return { error: 'unknown scenario ' + id };
  return { scenario: def, rows: genScenario(def), now: Object.assign({ day: TODAY }, def.now), request: def.request, LOCAL_ONLY: true };
}

// ---------- tool 2: leak detector + bill forecaster (pure maths) ----------
function detectLeak(rows) {
  const L = LIMITS, last = TODAY - 1, nights = [];
  let missing = 0, total = 0;
  for (let d = Math.max(1, last - 6); d <= TODAY; d++) {
    const nr = rows.filter(r => r.day === d && r.hour >= L.NIGHT_FIRST && r.hour <= L.NIGHT_LAST && r.occupied === 0);
    if (!nr.length) continue;
    total += nr.length; missing += nr.filter(r => r.water_lph === null).length;
    const vals = nr.filter(r => r.water_lph !== null).map(r => r.water_lph);
    if (vals.length) nights.push({ day: d, min: Math.min.apply(null, vals), n: vals.length });
  }
  if (total && missing / total > L.GAP_LIMIT) return { verdict: 'INSUFFICIENT_DATA', reason: 'Meter data is missing for ' + missing + ' of ' + total + ' night hours (limit ' + Math.round(L.GAP_LIMIT * 100) + '%), so no leak call can be made.', nights, est_lph: 0 };
  const flagged = nights.filter(n => n.min >= L.LEAK_MIN_LPH);
  let run = 0, best = 0;
  rows.forEach(r => { if (r.occupied === 0 && r.water_lph !== null && r.water_lph >= L.LEAK_MIN_LPH) { run++; best = Math.max(best, run); } else run = 0; });
  if (flagged.length >= L.LEAK_NIGHTS || best >= L.LEAK_RUN_HOURS) {
    const est = Math.round(flagged.length ? flagged.map(n => n.min).sort((a, b) => a - b)[Math.floor(flagged.length / 2)] : 0);
    const first = rows.find(r => r.occupied === 0 && r.water_lph !== null && r.water_lph >= L.LEAK_MIN_LPH);
    return { verdict: 'LEAK', est_lph: est, est_litres_per_day: est * 24, first_seen: first ? { day: first.day, hour: first.hour } : null, flagged_nights: flagged.length, longest_run_hours: best, nights, reason: 'Water flow stayed at or above ' + L.LEAK_MIN_LPH + ' L/h for hours when nobody was there (' + flagged.length + ' flagged nights, longest empty run ' + best + ' h). Estimated ' + est + ' L/h.' };
  }
  const watch = nights.filter(n => n.min >= L.WATCH_MIN_LPH && n.min < L.LEAK_MIN_LPH);
  if (watch.length >= 3) return { verdict: 'WATCH', est_lph: Math.round(watch[0].min), reason: 'A small constant night flow (about ' + Math.round(watch[0].min) + ' L/h on ' + watch.length + ' nights) is below the ' + L.LEAK_MIN_LPH + ' L/h leak rule. Worth watching.', nights };
  return { verdict: 'NO_LEAK', est_lph: 0, reason: 'Night-time flow when empty stays near zero.', nights };
}
function slabCost(units, slabs) { let left = units, from = 0; const steps = []; for (const s of slabs) { if (left <= 0) break; const room = s.upto - from, u = Math.min(left, room); steps.push({ from, to: s.upto === Infinity ? null : s.upto, units: Math.round(u * 10) / 10, rate: s.rate, cost: Math.round(u * s.rate * 100) / 100 }); left -= u; from = s.upto; } return { steps, total: Math.round(steps.reduce((a, s) => a + s.cost, 0) * 100) / 100 }; }
function billFor(litres, kwh) {
  const ig = litres / L_PER_IG, w = slabCost(ig, TARIFF.water.slabs), e = slabCost(kwh, TARIFF.electricity.slabs);
  const fuel = Math.round(kwh * TARIFF.electricity.fuel_surcharge_per_kwh * 100) / 100;
  return { water: { litres: Math.round(litres), imperial_gallons: Math.round(ig), steps: w.steps, cost: w.total }, electricity: { kwh: Math.round(kwh), steps: e.steps, fuel_surcharge: fuel, cost: Math.round((e.total + fuel) * 100) / 100 }, total_aed: Math.round((w.total + e.total + fuel) * 100) / 100 };
}
function forecastBill(rows, leak, nowHour) {
  const sum = (f) => rows.reduce((a, r) => a + (r[f] || 0), 0);
  const obsW = sum('water_lph'), obsE = sum('kwh');
  const base = rows.filter(r => r.day >= TODAY - 14 && r.day < TODAY);
  const avgW = base.reduce((a, r) => a + (r.water_lph || 0), 0) / 14, avgE = base.reduce((a, r) => a + (r.kwh || 0), 0) / 14;
  const remDays = (MONTH_DAYS - TODAY) + (24 - nowHour) / 24;
  const withLeak = billFor(obsW + avgW * remDays, obsE + avgE * remDays);
  let without = null, impact = 0;
  if (leak && leak.verdict === 'LEAK' && leak.first_seen) {
    const hoursSoFar = (TODAY - leak.first_seen.day) * 24 + (nowHour - leak.first_seen.hour);
    const removeObs = leak.est_lph * Math.max(0, hoursSoFar), removeRem = leak.est_lph * 24 * remDays;
    without = billFor(Math.max(0, obsW - removeObs) + Math.max(0, avgW - leak.est_lph * 24) * remDays, obsE + avgE * remDays);
    impact = Math.round((withLeak.total_aed - without.total_aed) * 100) / 100;
  }
  return { method: 'month so far + average of the last 14 full days x remaining days (a naive projection, not a prediction)', month_days: MONTH_DAYS, today: TODAY, with_leak: withLeak, without_leak: without, leak_bill_impact_aed: impact, tariff_verified: TARIFF.verified, tariff_source: TARIFF.source };
}
function run_leak_and_bill_forecaster(id) {
  const rec = get_local_meter_and_occupancy(id); if (rec.error) return rec;
  const leak = detectLeak(rec.rows), bill = forecastBill(rec.rows, leak, rec.now.hour);
  const slabs = bill.with_leak.electricity.steps.length;
  return { scenario_id: +id, leak, bill, elec_slab_count: slabs };
}

// ---------- guard 1: privacy filter (allow-list, not block-list) ----------
const ALLOWED_OUT = ['scenario_id', 'scenario_name', 'leak_verdict', 'est_leak_lph', 'est_leak_litres_per_day', 'leak_bill_impact_aed', 'bill_total_aed', 'water_cost_aed', 'electricity_cost_aed', 'elec_slabs_used', 'water_gallons', 'electricity_kwh', 'tariff_verified', 'guard_rule', 'guard_status', 'guard_reason', 'request_type', 'requested_setpoint_c', 'outdoor_c', 'task'];
const OCC_HINT = /occup|presence|room|schedule|people|empty/i;
function sanitize(payload, destination) {
  const kept = {}, stripped = [];
  Object.keys(payload).forEach(k => { if (ALLOWED_OUT.indexOf(k) >= 0 && !OCC_HINT.test(k)) kept[k] = payload[k]; else stripped.push(k); });
  const body = JSON.stringify(kept);
  if (OCC_HINT.test(Object.keys(kept).join(' '))) throw new Error('PrivacyViolation: occupancy-like field survived');
  if (OCC_HINT.test(body)) throw new Error('PrivacyViolation: occupancy-like text survived in a value');
  return { payload: kept, egress: { destination, sent_fields: Object.keys(kept), stripped_fields: stripped, bytes: body.length, occupancy_sent: false } };
}

// What the cloud model may see. Neutral vocabulary on purpose: no word that reveals whether anyone is in the building.
const PUBLIC_RULE = { occupied_over_limit: 'setpoint_above_comfort_limit', unoccupied_over_precool_ceiling: 'setpoint_above_precool_limit', cooling_off_in_heat: 'cooling_off_in_heat', privacy_export_blocked: 'export_blocked', needs_approval: 'needs_human_approval' };
const PUBLIC_REASON = { setpoint_above_comfort_limit: 'The requested setpoint is above the hard comfort limit.', setpoint_above_precool_limit: 'The requested setpoint is above the hard pre-cooling limit.', cooling_off_in_heat: 'Cooling may not be switched off in this heat.', export_blocked: 'Blocked by the privacy rule: raw building data never leaves the device.', needs_human_approval: 'Inside every safety limit; a person must still approve.' };
function buildOutbound(scn, leak, bill, guard, req) {
  const rule = PUBLIC_RULE[guard.rule] || 'needs_human_approval';
  return {
    scenario_id: scn.id, leak_verdict: leak.verdict, est_leak_lph: leak.est_lph || 0, est_leak_litres_per_day: leak.est_litres_per_day || 0,
    leak_bill_impact_aed: bill.leak_bill_impact_aed, bill_total_aed: bill.with_leak.total_aed, water_cost_aed: bill.with_leak.water.cost, electricity_cost_aed: bill.with_leak.electricity.cost,
    elec_slabs_used: bill.with_leak.electricity.steps.length, water_gallons: bill.with_leak.water.imperial_gallons, electricity_kwh: bill.with_leak.electricity.kwh, tariff_verified: TARIFF.verified,
    guard_rule: rule, guard_status: guard.status, guard_reason: PUBLIC_REASON[rule], request_type: req.type === 'EXPORT_OCCUPANCY' ? 'EXPORT_DATA' : req.type,
    requested_setpoint_c: req.setpoint_c === undefined ? null : req.setpoint_c, task: 'Explain these already-computed results to a facilities manager.'
  };
}

// ---------- guard 2: heat safety (hard limits, nothing can override) ----------
function heatGuard(req, state) {
  const L = LIMITS, B = (rule, reason, suggest) => ({ status: 'BLOCKED', rule, reason, suggested_setpoint_c: suggest === undefined ? null : suggest });
  if (req.type === 'EXPORT_OCCUPANCY') return B('privacy_export_blocked', 'Raw occupancy data is never sent off the device. Only totals and decisions may leave.');
  if (req.type === 'SETPOINT') {
    if (state.occupied && req.setpoint_c > L.OCCUPIED_MAX_C) return B('occupied_over_limit', 'Occupied rooms may never be set above ' + L.OCCUPIED_MAX_C + ' C. Requested ' + req.setpoint_c + ' C.', L.OCCUPIED_MAX_C);
    if (!state.occupied && req.setpoint_c > L.UNOCCUPIED_PRECOOL_MAX_C) return B('unoccupied_over_precool_ceiling', 'Pre-cooling an empty building may never be set above ' + L.UNOCCUPIED_PRECOOL_MAX_C + ' C. Requested ' + req.setpoint_c + ' C.', L.UNOCCUPIED_PRECOOL_MAX_C);
  }
  if (req.type === 'COOLING_OFF' && state.occupied && state.outdoor_c >= L.HEAT_OUTDOOR_C) return B('cooling_off_in_heat', 'Cooling cannot be switched off while people are inside and it is ' + state.outdoor_c + ' C outside (limit ' + L.HEAT_OUTDOOR_C + ' C).');
  return { status: 'NEEDS_APPROVAL', rule: 'needs_approval', reason: req.type === 'MAIN_WATER_SHUTOFF' ? 'Closing the main water valve always needs a person to approve.' : 'Inside every safety limit, but any cooling or valve change still needs a person to approve.', suggested_setpoint_c: null };
}

// ---------- approval + the single write gateway ----------
function applyReview(decision, reviewer) {
  const name = String(reviewer || '').replace(/\s+/g, ' ').trim().slice(0, 60);
  const wants = String(decision || '').toLowerCase().startsWith('approve');
  const approved = wants && name.length >= LIMITS.MIN_NAME_LEN;
  return { approved, reviewer: name || 'nobody', note: wants && !approved ? 'approval ignored: no reviewer name' : '' };
}
// the only function that changes the (simulated) building state: re-checks the limits, all-or-nothing
function writeGateway(req, state, device) {
  const snapshot = JSON.stringify(device);
  try {
    const g = heatGuard(req, state);
    if (g.status === 'BLOCKED') throw new Error('blocked at the gateway: ' + g.rule);
    if (req.type === 'SETPOINT') device.setpoint_c = req.setpoint_c;
    if (req.type === 'COOLING_OFF') device.cooling = 'off';
    if (req.type === 'MAIN_WATER_SHUTOFF') device.main_valve = 'closed';
    return { ok: true, device };
  } catch (e) { const back = JSON.parse(snapshot); return { ok: false, error: String(e.message), device: back, rolled_back: true }; }
}


// ===== node body: everything below runs ON THE DEVICE, in plain code =====
const sel = String($json['Scenario'] || '').trim();
const id = parseInt(sel, 10);
const run_id = 'ES-' + Date.now().toString(36).toUpperCase();
const trace = [];
const ev = (actor, step, detail) => trace.push({ ts: new Date().toISOString(), run_id, actor, step, detail });
const scn = SCENARIOS.find(s => s.id === id);
if (!scn) throw new Error('Unknown scenario: ' + sel);
ev('human', 'input', { scenario: sel });
const rec = get_local_meter_and_occupancy(id);
ev('tool', 'get_local_meter_and_occupancy', { rows: rec.rows.length, stays_on_device: true });
const out = run_leak_and_bill_forecaster(id);
ev('tool', 'run_leak_and_bill_forecaster', { leak: out.leak.verdict, est_lph: out.leak.est_lph, month_bill_aed: out.bill.with_leak.total_aed, tariff_verified: TARIFF.verified });
const state = { occupied: rec.now.occupied, outdoor_c: rec.now.outdoor_c };
const guard = heatGuard(scn.request, state);
ev('guard', 'heat_and_privacy_guard', { request: scn.request, state, status: guard.status, rule: guard.rule, reason: guard.reason });
const s = sanitize(buildOutbound(scn, out.leak, out.bill, guard, scn.request), 'groq (cloud LLM)');
ev('privacy', 'egress_filter', s.egress);
const last = rec.rows[rec.rows.length - 1];
const device = { setpoint_c: last.setpoint_c, cooling: 'on', main_valve: 'open' };
return [{ json: { run_id, scenario: { id: scn.id, name: scn.name, desc: scn.desc }, request: scn.request, state, device, leak: out.leak, bill: out.bill, guard, outbound: s.payload, egress: s.egress, trace } }];

const d = $json;
const system = 'You are the explainer inside EcoShield, a water and cooling saving agent for a school. You receive RESULTS that plain code already computed. ' +
  'You do not decide anything, you cannot change anything, and you must never claim that you did. Use ONLY the numbers in the JSON; do not calculate new ones and do not invent any. ' +
  'If tariff_verified is false, say the AED figures use an assumed tariff. Reply with JSON only: {"headline":"<=12 words","explanation":"2-3 plain sentences: what was found and what it costs","tip":"one practical next step for a person"}.';
const user = JSON.stringify(d.outbound);
if (/occup|presence|room|people|schedule|empty/i.test(user)) throw new Error('Egress check failed: occupancy-like text in the outbound payload');
const messages = [{ role: 'system', content: system }, { role: 'user', content: user }];
const trace = d.trace.slice();
trace.push({ ts: new Date().toISOString(), run_id: d.run_id, actor: 'privacy', step: 'egress_assertion', detail: { passed: true, outbound_bytes: user.length } });
return [{ json: Object.assign({}, d, { trace, llm: {
  groqBody: { model: 'openai/gpt-oss-120b', temperature: 0, max_tokens: 700, reasoning_effort: 'low', messages },
  ollamaBody: { model: 'qwen3:1.7b', stream: false, think: false, options: { temperature: 0, num_predict: 350 }, messages } } }) }];

const d = $('Build LLM prompt').first().json;
const j = $json || {};
const trace = d.trace.slice();
const ev = (actor, step, detail) => trace.push({ ts: new Date().toISOString(), run_id: d.run_id, actor, step, detail });
let provider = 'template', raw = '', tokens = null;
if (j.choices && j.choices[0] && j.choices[0].message) { provider = 'groq'; raw = String(j.choices[0].message.content || ''); tokens = j.usage ? j.usage.total_tokens : null; }
else if (j.message && j.message.content) { provider = 'ollama'; raw = String(j.message.content); tokens = (j.prompt_eval_count || 0) + (j.eval_count || 0); }
// the numbers the model is allowed to quote: the ones it was sent, plus the fixed limits
const allowed = new Set(['24', '27', '10', '38']);
const walk = (v) => { if (typeof v === 'number') { allowed.add(String(v)); allowed.add(String(Math.round(v))); allowed.add(String(Math.round(v * 10) / 10)); } else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
walk(d.outbound);
let llm = null, why = '';
if (provider !== 'template') {
  try {
    const m = raw.replace(/<think>[\s\S]*?<\/think>/g, '').match(/\{[\s\S]*\}/);
    const o = JSON.parse(m[0]);
    if (['headline', 'explanation', 'tip'].every(k => typeof o[k] === 'string' && o[k].trim())) {
      const text = o.headline + ' ' + o.explanation + ' ' + o.tip;
      const nums = (text.replace(/,/g, '').match(/\d+(\.\d+)?/g) || []);
      const bad = nums.filter(n => !allowed.has(n) && !allowed.has(String(Math.round(parseFloat(n)))) && !(Number.isInteger(parseFloat(n)) && parseFloat(n) <= 5));
      if (bad.length) why = 'AI quoted numbers it was never given: ' + bad.join(', ') + ' (text discarded)'; else llm = { headline: o.headline.trim(), explanation: o.explanation.trim(), tip: o.tip.trim() };
    } else why = 'AI reply missing fields';
  } catch (e) { why = 'AI reply was not valid JSON'; }
} else why = 'No AI provider answered (Groq and Ollama both failed or timed out)';
// plain-code fallback text: always available, built only from computed results
const o = d.outbound, L = d.leak;
const tmpl = {
  headline: L.verdict === 'LEAK' ? 'Probable leak: about ' + o.est_leak_lph + ' L/h flowing when the building is quiet' : (L.verdict === 'WATCH' ? 'Small constant night flow worth watching' : (L.verdict === 'INSUFFICIENT_DATA' ? 'Not enough meter data to judge leaks' : 'No leak found')),
  explanation: 'Forecast bill this month: AED ' + o.bill_total_aed + ' (assumed tariff' + (o.tariff_verified ? ', verified' : ', not verified') + '). ' + (L.verdict === 'LEAK' ? 'The leak adds about AED ' + o.leak_bill_impact_aed + ' to this month. ' : '') + 'Safety check: ' + o.guard_reason,
